// ============================================================
// ascii/KnightArt.js
// Arte ASCII de alta densidade para o protagonista (Cavaleiro).
// Baseado diretamente no arquivo de referência ascii-art.html:
// densidade de caracteres (@, %, #, *, +, =, -, :, .),
// sombreamento volumétrico, pluma carmesim, placas de aço e reflexos.
// ============================================================
import knightReferenceRle from './knight_reference_rle.js';
import { MATERIALS } from './AsciiPalette.js';

// Função de paleta inteligente para sprites do Cavaleiro:
// Converte os caracteres estruturais e de densidade nos materiais corretos
// (Pluma/Manto Carmesim, Armadura de Aço, Guarda Dourada, Fio da Espada, Fissura do Elmo)
export function knightPalette(ch, x, y, context = {}) {
  // Pluma no topo da cabeça (linhas superiores no centro/traseira)
  if (context.isPlume || (y < 7 && ch !== ' ')) {
    return MATERIALS.CRIMSON_CLOTH[ch] || '#b5162c';
  }

  // Manto/capa lateral ou posterior
  if (context.isCape) {
    return MATERIALS.CRIMSON_CLOTH[ch] || '#7e0729';
  }

  // Visor do elmo (fenda escura com reflexo carmesim/laranja sutil)
  if (context.isVisor) {
    if (ch === '-' || ch === '=') return '#ff3344';
    return '#110005';
  }

  // Guarda e pomo dourados
  if (context.isGold || ch === '$') {
    return MATERIALS.GOLD[ch] || '#f2c56d';
  }

  // Lâmina e placas de aço (padrão)
  return MATERIALS.STEEL[ch] || '#4b4760';
}

